      "pertinente": true,
      "tipo": "opiniao",
      "achados": [
        {
          "proposicao": "O texto apresenta a purificação de grandes volumes de gás natural ácido como demandando um processo eficiente, regenerável, simples e relativamente livre de problemas operacionais.",
